int main(){std::string e;TensorRuntime rt;auto a=rt.createTensor(TensorShape({2,3}),TensorDType::F32,e),b=rt.createTensor(TensorShape({3}),TensorDType::F32,e);if(!a.valid()||!b.valid())return 1;for(int i=0;i<6;i++)((float*)a.mutableData())[i]=float(i+1);for(int i=0;i<3;i++)((float*)b.mutableData())[i]=float(10+i);Tensor out;if(!localimage::ops::add(a,b,out,e))return 2;if(std::fabs(((float*)out.data())[5]-18)>1e-6)return 3;Tensor u;if(!localimage::ops::unary(a,u,"silu",e))return 4;Tensor m1=rt.createTensor(TensorShape({2,3}),TensorDType::F32,e),m2=rt.createTensor(TensorShape({3,2}),TensorDType::F32,e);for(int i=0;i<6;i++){((float*)m1.mutableData())[i]=float(i+1);((float*)m2.mutableData())[i]=float(i+1);}Tensor mm;if(!localimage::ops::matmul(m1,m2,mm,e)||std::fabs(((float*)mm.data())[0]-22)>1e-6)return 5;Tensor lnG=rt.createTensor(TensorShape({3}),TensorDType::F32,e);for(int i=0;i<3;i++)((float*)lnG.mutableData())[i]=1;Tensor ln;if(!localimage::ops::layerNorm(a,lnG,nullptr,1e-5,ln,e))return 6;Tensor sm;if(!localimage::ops::softmax(a,1,sm,e))return 7;for(int r=0;r<2;r++){double s=0;for(int j=0;j<3;j++)s+=((float*)sm.data())[r*3+j];if(std::fabs(s-1)>1e-5)return 8;}localimage::graph::Graph g;auto v0=g.addValue("a",a.shape(),a.dtype()),v1=g.addValue("b",b.shape(),b.dtype()),v2=g.addValue("c",out.shape(),out.dtype());auto n=g.addNode(localimage::graph::OpType::Add,{v0,v1},"add");if(!g.setNodeOutputs(n,{v2},e))return 9;std::vector<uint32_t>order;if(!g.topologicalSort(order,e)||order.size()!=1)return 10;std::cout<<"M5 CPU operator foundation: PASS\nM6 graph construction/topological sort: PASS\n";std::cout<<"M7 CLIP: NOT VERIFIED\nM8 SD1.5 UNet: NOT VERIFIED\n";return 0;}
